insert into na_rubric_items (id, nuanced_analysis_id, qid, base_qid, question_number, question_text, answer_key, command_term, marks, question_marks, open_rubric, source)
values
  ('a85ddd30-a8ac-5434-94e7-6bc7b124a566', '41e8ca4e-087d-4146-b364-19139d659343', 'Q1', 'Q1', 1, 'Calculate each of the following without a calculator. (a) 12 - 5 (b) 12 + (-5) (c) 20 / 4 (d) 20 x 1/4', '(a) 7. (b) 7. (c) 5. (d) 5.', 'Calculate', 3, 4, null, 'authored_from_print'),
  ('a647f738-5bb7-5e1d-ba2a-0db462be6b93', '41e8ca4e-087d-4146-b364-19139d659343', 'Q1(e)', 'Q1', 1, 'Calculate each of the following without a calculator. (e) Write down one thing you notice comparing (a) to (b), and (c) to (d).', '(e) Each pair gives the same value -- subtracting 5 and adding -5 agree; dividing by 4 and multiplying by 1/4 agree.', 'Write down', 1, 4, null, 'authored_from_print'),
  ('c6efe209-bb25-5f89-97b3-92515f633aca', '41e8ca4e-087d-4146-b364-19139d659343', 'ACTIVITY[MY NOTICINGS FROM THE SANDBOX]', 'ACTIVITY[MY NOTICINGS FROM THE SANDBOX]', 0, 'Desmos slider sandbox: write down what you notice about n - 4 and n + (-4) as the slider moves. Thinking space, not marked.', null, null, null, 0, null, 'authored_from_print'),
  ('85e98b56-12f1-5a53-8be4-a94c159541ee', '41e8ca4e-087d-4146-b364-19139d659343', 'Q2', 'Q2', 2, 'Write down the constant terms, coefficients, variables, and number of terms for: -x^3 y^6 - 10x^4y - 9y^2 + 9', 'Constant term: 9. Coefficients: -1, -10, -9. Variables: x, y. Number of terms: 4.', 'Write down', 6, 6, null, 'authored_from_print'),
  ('853bf3ef-ade5-55a7-a514-c3859c92e744', '41e8ca4e-087d-4146-b364-19139d659343', 'Q3', 'Q3', 3, 'Recall from Section A.1 (Q13) that a student wrote ''5 fewer packages of pencils than p packages of pens'' as 5 - p, and that this was identified as a subtraction-order reversal. (a) Using the formal definition a - b := a + (-b), rewrite ''5 fewer than p'' starting from the phrase ''start at p, then add the opposite of 5.''', '(a) ''Start at p, add the opposite of 5'' = p + (-5) = p - 5.', null, 2, 6, null, 'authored_from_print'),
  ('3270ebbf-41ec-5578-b53a-6c5dd3f4cdcb', '41e8ca4e-087d-4146-b364-19139d659343', 'Q3(b)', 'Q3', 3, 'Recall from Section A.1 (Q13) that a student wrote ''5 fewer packages of pencils than p packages of pens'' as 5 - p, and that this was identified as a subtraction-order reversal. (b) Explain why the formal definition makes it impossible to accidentally write 5 - p for this phrase, in a way that simply remembering ''put the bigger one first'' does not.', '(b) The formal definition fixes the order conceptually -- you always start at the first-named quantity and add the opposite of the second, regardless of word order. There is no ''bigger number first'' rule to misremember because the rule never references size.', 'Explain', 4, 6, null, 'authored_from_print'),
  ('3a91f67a-9716-55df-adae-d229e09359ba', '41e8ca4e-087d-4146-b364-19139d659343', 'Q4', 'Q4', 4, 'Translate each into an expression, using the formal definitions where helpful. Let n stand for the unknown number. (a) 7 less than a number. (b) A number decreased by 7. (c) The difference of a number and 7. (d) 7 decreased by a number. (e) Explain why (a), (b), and (c) all give the same expression, while (d) gives a different one.', '(a)(b)(c) all give n - 7. (d) gives 7 - n. (e) (a)-(c) all describe ''start at n, subtract 7''; (d) describes ''start at 7, subtract n'' -- a genuinely different starting point.', 'Explain', 5, 5, null, 'authored_from_print'),
  ('06b4adc2-81ab-556e-9934-9f5af53009a1', '41e8ca4e-087d-4146-b364-19139d659343', 'Q5', 'Q5', 5, 'Broken Math Critique. A student is asked to write ''the quotient of 5 and a number n'' as an expression, and writes 5/n = n/5, arguing that ''division is commutative, just like multiplication.'' (a) Take n = 2. Calculate 5/n and n/5. Explain why the student''s reasoning fails.', '(a) 5/2 = 2.5; 2/5 = 0.4. Not equal, so division is not commutative.', 'Calculate', 2, 5, null, 'authored_from_print'),
  ('53eb9c13-0d20-5dc3-88ef-10abb20a1388', '41e8ca4e-087d-4146-b364-19139d659343', 'Q5(b)', 'Q5', 5, 'Broken Math Critique. A student is asked to write ''the quotient of 5 and a number n'' as an expression, and writes 5/n = n/5, arguing that ''division is commutative, just like multiplication.'' (b) Using the formal definition a / b := a x 1/b, explain why division is not commutative even though multiplication is. (Hint: is 1/b the same as 1/a?)', '(b) 1/b is not equal to 1/a in general (unless a = b), so a x 1/b is not equal to b x 1/a in general -- the definition itself shows why commutativity fails.', null, 3, 5, null, 'authored_from_print'),
  ('1ffb2e86-bf66-58ac-bcc9-91703ac1db06', '41e8ca4e-087d-4146-b364-19139d659343', 'Q6', 'Q6', 6, 'Write an expression for: (a) the difference of three times a number and 4. (b) the sum of twice a number and half the number. (c) six times the sum of a number and 15.', '(a) 3n - 4. (b) 2n + n/2. (c) 6(n + 15).', 'Write an expression', 4, 4, null, 'authored_from_print'),
  ('f0e88a1a-727f-5f75-a050-cd88f1c19d9d', '41e8ca4e-087d-4146-b364-19139d659343', 'Q7', 'Q7', 7, 'Write an expression for each. Let p, q, a, b be the numbers named. (a) the sum of p and the square of q. (b) the square of the sum of p and q. (c) the square root of all of 2 times a minus b.', '(a) p + q^2. (b) (p + q)^2. (c) sqrt(2a - b).', 'Write an expression', 6, 6, null, 'authored_from_print'),
  ('ea0d8303-6f8d-51ac-bc59-970484b320d5', '41e8ca4e-087d-4146-b364-19139d659343', 'Q8', 'Q8', 8, 'Compare your answers to the previous question''s (a) and (b). Explain, using p = 2 and q = 3, why these two expressions are not equivalent -- even though both sentences use the words ''sum,'' ''square,'' p, and q.', 'With p=2, q=3: p + q^2 gives 2 + 9 = 11. (p+q)^2 gives 25. Not equal -- order of squaring vs. summing changes the result.', 'Compare', 4, 4, null, 'authored_from_print'),
  ('ac22b741-50f1-5233-8186-532a9f38e6b0', '41e8ca4e-087d-4146-b364-19139d659343', 'Q9', 'Q9', 9, 'Peter is planning to buy a new computer that costs p dollars. He knows he has to pay 6% sales tax on the computer. (a) Write an expression for the amount of sales tax he will pay. (b) Write an expression for the total price of the computer, including tax.', '(a) 0.06p. (b) p + 0.06p (accept 1.06p).', 'Write an expression', 3, 3, null, 'authored_from_print'),
  ('9b7a5134-e7a5-57a9-905d-356851be97c4', '41e8ca4e-087d-4146-b364-19139d659343', 'Q10', 'Q10', 10, 'George is buying watermelons and pineapples to make a fruit salad. He buys w watermelons at $4.49 each and p pineapples at $5 each. Write an expression to represent the cost of the fruit salad.', '4.49w + 5p.', 'Write an expression', 3, 3, null, 'authored_from_print'),
  ('b6b5a4b3-02b2-5f5b-9ab0-1ea87d9d1021', '41e8ca4e-087d-4146-b364-19139d659343', 'Q11', 'Q11', 11, 'Sandra buys 5 fewer packages of pencils than p packages of pens. Pencils cost $2.50 per package and pens cost $3 per package. Write an expression to represent the total amount she will pay. This is the exact scenario from A.1 Q14, with new prices. Use the earlier formal reasoning, not memory of the old answer.', 'Pencils: p - 5 packages at $2.50; pens: p packages at $3. Total: 2.50(p - 5) + 3p.', 'Write an expression', 4, 4, null, 'authored_from_print'),
  ('f75251da-36a4-5cfc-aa2b-d8da0351dd9b', '41e8ca4e-087d-4146-b364-19139d659343', 'Q12', 'Q12', 12, 'A vehicle salesman shows Nigel a red bus and a green bus. The red bus has 12 fewer seats than three times the number of seats in the green bus. If the green bus has g seats, write an expression for the number of seats in the red bus. Show your reasoning, not just the final expression -- name the two quantities being compared before you combine them. Keep this result -- Part 4 begins by asking you to use it, not re-derive it.', '3g - 12.', 'Show', 5, 5, null, 'authored_from_print'),
  ('9390a3cd-658a-5a2b-8da4-92954dcdb602', '41e8ca4e-087d-4146-b364-19139d659343', 'Q13', 'Q13', 13, 'A vehicle salesman shows Nigel a red bus and a green bus. The red bus has 12 fewer seats than three times the number of seats in the green bus. (a) State the expression you found earlier for the number of seats in the red bus, if the green bus has g seats.', '(a) 3g - 12.', 'State', 1, 4, null, 'authored_from_print'),
  ('09a8b382-dd33-5405-9dd1-3af704b33e75', '41e8ca4e-087d-4146-b364-19139d659343', 'Q13(b)', 'Q13', 13, 'A vehicle salesman shows Nigel a red bus and a green bus. The red bus has 12 fewer seats than three times the number of seats in the green bus. (b) Hence find the number of seats in the red bus, if the green bus has 18 seats.', '(b) 3(18) - 12 = 54 - 12 = 42 seats. Full marks require visible substitution into 3g - 12, not a fresh calculation.', 'Hence', 3, 4, null, 'authored_from_print'),
  ('d5f7289b-5945-5691-9f57-d116d0cd7a2e', '41e8ca4e-087d-4146-b364-19139d659343', 'Q14', 'Q14', 14, 'Chris buys p pairs of pants and 4 more shirts than pairs of pants. Shirts cost $18 each and pants cost $25 each. (a) Write an expression for the number of shirts Chris buys, in terms of p.', '(a) p + 4.', 'Write an expression', 1, 6, null, 'authored_from_print'),
  ('435fed7e-fcc9-55b5-bc29-3bfcaa805e43', '41e8ca4e-087d-4146-b364-19139d659343', 'Q14(b)', 'Q14', 14, 'Chris buys p pairs of pants and 4 more shirts than pairs of pants. Shirts cost $18 each and pants cost $25 each. (b) Write an expression for the total cost of her purchase. (You should get something matching the form 25p + 18(p + 4).)', '(b) 25p + 18(p + 4).', 'Write an expression', 2, 6, null, 'authored_from_print'),
  ('3fa49e65-c5eb-595f-941c-09ae63a6f3db', '41e8ca4e-087d-4146-b364-19139d659343', 'Q14(c)', 'Q14', 14, 'Chris buys p pairs of pants and 4 more shirts than pairs of pants. Shirts cost $18 each and pants cost $25 each. (c) In the expression 18(p + 4), is (p + 4) a factor or a term? Explain your reasoning.', '(c) (p + 4) is a factor of the term 18(p + 4) -- it is being multiplied by 18.', 'Explain', 2, 6, null, 'authored_from_print'),
  ('7f3d488e-73e0-5768-8a09-ecb4134e8b60', '41e8ca4e-087d-4146-b364-19139d659343', 'Q14(d)', 'Q14', 14, 'Chris buys p pairs of pants and 4 more shirts than pairs of pants. Shirts cost $18 each and pants cost $25 each. (d) Explain what the factor 25 represents in the term 25p, in the context of this situation.', '(d) 25 represents the price in dollars of one pair of pants.', 'Explain', 1, 6, null, 'authored_from_print'),
  ('f1468ae2-1365-50fd-8309-67c4b1d31364', '41e8ca4e-087d-4146-b364-19139d659343', 'Q15', 'Q15', 15, 'Hence, using your answer to the previous question''s (b), explain what the expression 25p + 18(p + 4) represents as a whole, and explain what the more complicated expression (25p + 18(p + 4)) / 25p would represent if you were to calculate it. You do not need to simplify it -- only explain what quantity it describes.', '25p + 18(p+4) is the total cost of the purchase. Dividing that total by 25p (the cost of the pants alone) gives the ratio of total spending to pants-only spending -- for every dollar spent on pants, how many total dollars were spent.', 'Hence', 5, 5, null, 'authored_from_print'),
  ('45b82649-a847-5b0e-88fd-b2b24c759d46', '41e8ca4e-087d-4146-b364-19139d659343', 'Q16', 'Q16', 16, 'Using your expression from Part 2 (b), calculate the total price of a computer that costs p = $1,200 before tax.', '1200 + 0.06(1200) = 1272.', null, 3, 3, null, 'authored_from_print'),
  ('997e4538-10fc-5841-a20b-6624c1eff3d5', '41e8ca4e-087d-4146-b364-19139d659343', 'Q17', 'Q17', 17, 'Broken Math Critique. A student computes the total price of Peter''s computer as p + 6, reasoning that ''6% tax means you add 6.'' (a) Take p = 1200. Calculate the student''s total, and calculate the correct total using the earlier expression. Explain, using dollar amounts, why the student''s version cannot be right.', '(a) Student: 1206. Correct: 1272. Difference of $66 -- the student added 6 dollars instead of 6 percent of 1200 dollars.', 'Calculate', 3, 5, null, 'authored_from_print'),
  ('33cb0168-1e93-5d87-85b9-c18f0c464b31', '41e8ca4e-087d-4146-b364-19139d659343', 'Q17(b)', 'Q17', 17, 'Broken Math Critique. A student computes the total price of Peter''s computer as p + 6, reasoning that ''6% tax means you add 6.'' (b) Explain the specific misunderstanding of ''percent'' that produced the student''s error.', '(b) The student treated ''6%'' as the number 6 rather than as 6/100 of the base amount -- ignoring that percent is a rate relative to a base, not a flat quantity.', 'Explain', 2, 5, null, 'authored_from_print'),
  ('6fd4294e-06fe-5c71-9071-e67fe02310aa', '41e8ca4e-087d-4146-b364-19139d659343', 'Q18', 'Q18', 18, 'A store advertises ''20% off, then an additional 10% off the discounted price'' on an item that originally costs c dollars. (a) Write an expression for the price after the first discount.', '(a) 0.8c.', 'Write an expression', 1, 6, null, 'authored_from_print'),
  ('8de25032-2d39-5832-b182-91ab316ceba8', '41e8ca4e-087d-4146-b364-19139d659343', 'Q18(b)', 'Q18', 18, 'A store advertises ''20% off, then an additional 10% off the discounted price'' on an item that originally costs c dollars. (b) Hence write an expression for the price after both discounts, using your answer to (a) -- do not start over from c.', '(b) 0.9(0.8c) = 0.72c.', 'Hence', 2, 6, null, 'authored_from_print'),
  ('3a5470dc-42cc-51b8-9c79-ac5d4e8e36b7', '41e8ca4e-087d-4146-b364-19139d659343', 'Q18(c)', 'Q18', 18, 'A store advertises ''20% off, then an additional 10% off the discounted price'' on an item that originally costs c dollars. (c) Determine whether ''20% off then 10% off'' gives the same final price as a single ''30% off'' discount. Justify your answer using c = 100.', '(c) With c = 100: two-step gives $72; single 30% off gives $70. Not the same -- sequential percentage discounts compound multiplicatively, they don''t add.', 'Determine', 3, 6, null, 'authored_from_print'),
  ('f71eb7fc-f3e1-52b3-8160-0abfb7c6ce56', '41e8ca4e-087d-4146-b364-19139d659343', 'Q19', 'Q19', 19, 'List at least five ideas, words, or results that this analysis confirmed or connected for you. Use a table: the idea / where it appeared (Q number) / what it connected to. At least one row must reference Section A.1.', null, 'List', 5, 5, 'List at least five ideas, words or results this analysis confirmed or connected, using the 3-column table (the idea / where it appeared, by Q number / what it connected to). At least one row must reference Section A.1. Grade on: (a) count >= 5, (b) each row cites a real Q number from this packet, (c) >= 1 row references A.1, (d) the stated connection is mathematically sensible -- not on matching a fixed answer.', 'authored_from_print'),
  ('f1e4eaf5-c8dc-56f2-ab06-d3b9f00f7e56', '41e8ca4e-087d-4146-b364-19139d659343', 'Q20', 'Q20', 20, 'Section A.1 warned about writing ''5 fewer than p'' as 5 - p. This packet gave you a formal definition, a - b := a + (-b), meant to prevent that error permanently. Explain whether the formal definition actually solved the problem for you, or whether you still find yourself relying on a memorised order. Be honest -- this is not scored on which answer you give, only on how carefully you examine your own thinking.', null, 'Explain', 4, 4, null, 'authored_from_print'),
  ('f176c39a-1b83-5e93-82a1-cd3dc66c8a1f', '41e8ca4e-087d-4146-b364-19139d659343', 'Q21', 'Q21', 21, 'Return to the two TOK provocations on page 3. Choose one. Take a position and defend it, using a specific numbered result from this packet as your evidence.', null, null, 6, 6, null, 'authored_from_print');
